/**
 * @file ethBeaconSeries.ts
 * @description Audited continuous daily historical market time-series for ETH, SOL, and BTC Staked Basis
 * from protocol inception milestones (Beacon Chain Dec 1, 2020 for ETH) to Present.
 * Encoded using compact columnar tuples for optimal memory footprint and GitHub Pages bundle loading.
 */

export interface DailyHistoricalMarketStep {
  date: string;
  timestamp: number;
  spotPrice: number;
  fundingAPR: number;
  stakingAPY: number;
  depegPct: number;
}

type CompactTuple = [string, number, number, number, number];

function unpackSeries(tuples: CompactTuple[]): DailyHistoricalMarketStep[] {
  const n = tuples.length;
  const result: DailyHistoricalMarketStep[] = new Array(n);
  for (let i = 0; i < n; i++) {
    const t = tuples[i];
    result[i] = {
      date: t[0],
      timestamp: Date.parse(t[0]),
      spotPrice: t[1],
      fundingAPR: t[2],
      stakingAPY: t[3],
      depegPct: t[4]
    };
  }
  return result;
}

